BEGIN TRANSACTION;
CREATE TABLE assessments(
  assessment_id INTEGER PRIMARY KEY AUTOINCREMENT, institution TEXT, dimension_scores TEXT,
  weighted_score REAL, level INTEGER, assessed_by TEXT, assessed_at TEXT, capped INTEGER);
CREATE TABLE decisions(
  decision_id INTEGER PRIMARY KEY AUTOINCREMENT, model_id INTEGER NOT NULL, features TEXT NOT NULL,
  prediction INTEGER NOT NULL, score REAL, subject_pseudonym TEXT, created_at TEXT NOT NULL,
  outcome INTEGER);
CREATE TABLE drift_results(
  drift_id INTEGER PRIMARY KEY AUTOINCREMENT, run_id INTEGER NOT NULL, feature TEXT, test TEXT,
  statistic REAL, p_value REAL, drifted INTEGER, p_adjusted REAL);
CREATE TABLE explanations(
  explanation_id INTEGER PRIMARY KEY AUTOINCREMENT, decision_id INTEGER NOT NULL, method TEXT NOT NULL,
  attributions TEXT, base_value REAL, generated_at TEXT);
CREATE TABLE findings(
  finding_id INTEGER PRIMARY KEY AUTOINCREMENT, run_id INTEGER, policy_id INTEGER, model_id INTEGER,
  rule_id TEXT, severity TEXT, status TEXT, owner TEXT, message TEXT, justification TEXT,
  raised_at TEXT, closed_at TEXT, supersedes_finding_id INTEGER, recorded_by TEXT);
CREATE TABLE models(
  model_id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, owner TEXT, purpose TEXT,
  version TEXT, protected_attributes TEXT, thresholds TEXT, endpoint_url TEXT, review_date TEXT,
  artifact TEXT);
CREATE TABLE monitoring_runs(
  run_id INTEGER PRIMARY KEY AUTOINCREMENT, model_id INTEGER NOT NULL, window_start TEXT, window_end TEXT,
  metrics TEXT, policy_version INTEGER, created_at TEXT, triggered_by TEXT);
CREATE TABLE policies(
  policy_id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, rego_source TEXT NOT NULL,
  version INTEGER NOT NULL, effective_from TEXT, approved_by TEXT);

violation[{"rule_id": "NO_OWNER", "severity": "high", "message": "Model has no named owner"}] {
	input.accountability.owner == ""
}

violation[{"rule_id": "REVIEW_OVERDUE", "severity": "medium", "message": "Scheduled model review date has passed"}] {
	input.accountability.review_overdue == true
}

violation[{"rule_id": "DOC_INCOMPLETE", "severity": "low", "message": "Model documentation (purpose, version, protected attributes) is incomplete"}] {
	input.accountability.documentation_complete == false
}
',1,'2000-01-01T00:00:00','admin');

violation[{"rule_id": "DRIFT_FEATURE", "severity": "medium", "message": msg}] {
	count(input.drift.drifted_features) > 0
	msg := sprintf("Input drift detected in: %v", [concat(", ", input.drift.drifted_features)])
}

violation[{"rule_id": "DRIFT_PREDICTION", "severity": "high", "message": msg}] {
	input.drift.prediction.drifted == true
	shift := round(input.drift.prediction.shift * 1000) / 10
	msg := sprintf("Approval rate has shifted by %v percentage points against the reference window", [shift])
}
',1,'2000-01-01T00:00:00','admin');

# Every decision must have an explanation on file (coverage must be 100%)
violation[{"rule_id": "EXPLAIN_REQUIRED", "severity": "high", "message": msg}] {
	input.explainability.coverage < 1.0
	msg := sprintf("Explanation coverage is %v%%; every decision must be explainable", [round(input.explainability.coverage * 1000) / 10])
}
',1,'2000-01-01T00:00:00','admin');

# Disparate impact ratio below the four-fifths convention (default 0.80)
violation[{"rule_id": "DI_RATIO", "severity": "high", "message": msg}] {
	input.metrics.di_ratio != null
	input.metrics.di_ratio < input.model.thresholds.di_min
	msg := sprintf("Disparate impact ratio %v is below the minimum %v", [round(input.metrics.di_ratio * 100) / 100, input.model.thresholds.di_min])
}

# Equal opportunity difference above tolerance (default 0.10)
violation[{"rule_id": "EO_DIFF", "severity": "medium", "message": msg}] {
	input.metrics.eo_diff != null
	abs(input.metrics.eo_diff) > input.model.thresholds.eo_max
	msg := sprintf("Equal opportunity difference %v exceeds tolerance %v", [round(abs(input.metrics.eo_diff) * 100) / 100, input.model.thresholds.eo_max])
}

# F1: the protected attribute itself carries a material share of the model''s explanations
violation[{"rule_id": "GENDER_ATTRIBUTION", "severity": "high", "message": msg}] {
	input.explainability.protected_share != null
	input.explainability.protected_share > input.model.thresholds.protected_share_max
	msg := sprintf("Gender accounts for %v%% of total explanation weight (limit %v%%): the model relies directly on a protected attribute", [round(input.explainability.protected_share * 1000) / 10, round(input.model.thresholds.protected_share_max * 1000) / 10])
}
',1,'2000-01-01T00:00:00','admin');
CREATE TABLE users(
  user_id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL, role TEXT NOT NULL, display_name TEXT, created_at TEXT);
CREATE INDEX ix_dec_model_time ON decisions(model_id, created_at);
CREATE INDEX ix_expl_dec ON explanations(decision_id, method);
DELETE FROM "sqlite_sequence";
COMMIT;
